import {rankText,wild} from './guandan.mjs';
export function handCard(c,level,{selected=false,disabled=false,small=false,assignment=null}={}){const joker=c.r>14,red=c.s==='♥'||c.s==='♦',w=wild(c,level),label=(joker?'':c.s)+rankText(c.r);return`<${small?'span':'button'} class="gd-card ${joker?'joker':''} ${red?'red':''} ${w?'wild':''} ${selected?'picked':''} ${small?'small':''}" ${small?'':`data-gcard="${c.id}" aria-pressed="${selected}" ${disabled?'disabled':''}`} aria-label="${label}${w?'，逢人配':''}"><b>${rankText(c.r)}</b><i>${joker?'★':c.s}</i>${w?'<em>配</em>':c.r===level?'<em>级</em>':''}${assignment&&w&&assignment.r!==c.r?'<small>作 '+rankText(assignment.r)+'</small>':''}</${small?'span':'button'}>`}
